def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,1)]
    def owner(y,x):
        dmin=min(abs(y-r)+abs(x-c) for r,c,_ in markers)
        return [(r,c,v) for r,c,v in markers if abs(y-r)+abs(x-c)==dmin]
    for r,c,color in markers:
        left=c
        while left>0 and grid[r][left-1] in (1,color): left-=1
        right=c
        while right+1<w and grid[r][right+1] in (1,color): right+=1
        top=r
        while top>0 and grid[top-1][c] in (1,color): top-=1
        bot=r
        while bot+1<h and grid[bot+1][c] in (1,color): bot+=1
        n=min(right-left+1, bot-top+1, 7)
        n=max(n,3)
        patch=max(1,n-2)
        for y in range(h-n+1):
            for x in range(w-n+1):
                if not all(grid[yy][xx] in (1,color) for yy in range(y,y+n) for xx in range(x,x+n)):
                    continue
                if not all(any(v==color for _,_,v in owner(yy,xx)) for yy in range(y,y+n) for xx in range(x,x+n)):
                    continue
                # Ignore a square that is merely contained in a larger solid square.
                larger=False
                for yy in range(max(0,y-1),min(y,h-n-1)+1):
                    for xx in range(max(0,x-1),min(x,w-n-1)+1):
                        if yy<=y and yy+n+1>=y+n and xx<=x and xx+n+1>=x+n:
                            if all(grid[a][b] in (1,color) for a in range(yy,yy+n+1) for b in range(xx,xx+n+1)):
                                larger=True
                if larger: continue
                sy=y+(n-patch)//2; sx=x+(n-patch)//2
                for yy in range(sy,sy+patch):
                    for xx in range(sx,sx+patch):
                        if grid[yy][xx] in (1,color): out[yy][xx]=color
    return out

